mapper.select:
SELECT 
    c.*,
    e.name as ownerEmployeeName
FROM customer c
LEFT JOIN employee e ON c.owner_employee_id = e.id
WHERE c.is_deleted = 0

    AND c.customer_name LIKE CONCAT('%', #{params.customerName}, '%')


    AND c.customer_type = #{params.customerType}


    AND c.customer_status = #{params.customerStatus}


    AND c.customer_source = #{params.customerSource}


    AND c.owner_employee_id = #{params.ownerEmployeeId}


    AND c.industry = #{params.industry}


    AND c.contact_phone LIKE CONCAT('%', #{params.contactPhone}, '%')


    AND c.contact_email LIKE CONCAT('%', #{params.contactEmail}, '%')


    AND c.created_at >= #{params.startDate}


    AND c.created_at <= #{params.endDate}

ORDER BY c.created_at DESC

SELECT COUNT(*) as totalCount, COUNT(CASE WHEN DATE(created_at) = CURDATE() THEN 1 END) as todayCount, COUNT(CASE WHEN DATE(created_at) >= DATE_SUB(CURDATE(), INTERVAL 7 DAY) THEN 1 END) as weekCount, COUNT(CASE WHEN DATE(created_at) >= DATE_SUB(CURDATE(), INTERVAL 30 DAY) THEN 1 END) as monthCount, COUNT(CASE WHEN customer_type = 'individual' THEN 1 END) as individualCount, COUNT(CASE WHEN customer_type = 'corporate' THEN 1 END) as corporateCount, COUNT(CASE WHEN customer_status = 'potential' THEN 1 END) as potentialCount, COUNT(CASE WHEN customer_status = 'confirmed' THEN 1 END) as confirmedCount, COUNT(CASE WHEN customer_status = 'lost' THEN 1 END) as lostCount FROM customer WHERE is_deleted = 0
AND created_at >= #{params.startDate}
AND created_at <= #{params.endDate}
AND owner_employee_id = #{params.ownerEmployeeId}

SELECT COUNT(*)
FROM customer
WHERE customer_name = #{customerName}
AND is_deleted = 0

    AND customer_id != #{customerId}

SELECT COUNT(*)
FROM customer
WHERE contact_phone = #{phone}
AND is_deleted = 0

    AND customer_id != #{customerId}

SELECT COUNT(*)
FROM customer
WHERE contact_email = #{email}
AND is_deleted = 0

    AND customer_id != #{customerId}

